  // markForCheck - schedule check
  loadData() {
    this.dataService.getData().subscribe(data => {
      this.data = data;
      this.cdr.markForCheck(); // Marks component for checking
    });
  }

  // detectChanges - immediate check
  updateUI() {
    this.data = newData;
    this.cdr.detectChanges(); // Immediately run change detection
  }

  // detach/reattach - control detection entirely
  stopChecking() {
    this.cdr.detach(); // Stop checking
  }

