// Service with error handling
@Injectable({ providedIn: 'root' })
export class UserService {
  getUsers(): Observable<User[]> {
    return this.http.get<User[]>('/api/users').pipe(
      catchError(error => {
        // Log error
        console.error('Error fetching users:', error);

        // Display user-friendly message
        this.notificationService.showError('Failed to load users');

        // Rethrow or return fallback
        return throwError(() => this.handleError(error));
      })
    );
  }

  private handleError(error: HttpErrorResponse): Error {
    let message = 'An error occurred';

    if (error.error instanceof ErrorEvent) {
      // Client-side error
      message = `Client error: ${error.error.message}`;
    } else {
      // Server-side error
      switch (error.status) {
        case 400: message = 'Bad request'; break;
        case 401: message = 'Unauthorized - please login'; break;
        case 403: message = 'Forbidden - insufficient permissions'; break;
        case 404: message = 'Resource not found'; break;
        case 500: message = 'Server error - please try later'; break;
        default: message = `Error ${error.status}: ${error.message}`;
      }
    }

    return new Error(message);
  }

  // Retry failed requests
  getUsersWithRetry(): Observable<User[]> {
    return this.http.get<User[]>('/api/users').pipe(
      retry(3), // Retry 3 times
      catchError(error => {
        console.error('Failed after 3 retries:', error);
        return throwError(error);
      })
    );
  }
}

