// PROBLEM: Race condition
// User types: a, ab, abc
// Requests fire: search('a'), search('ab'), search('abc')
// If search('a') responds last, it overwrites 'abc' results

// WRONG - race condition
search(value: string) {
  this.searchService.search(value).subscribe(results => {
    this.results = results; // Could be stale data
  });
}

// SOLUTION 1: switchMap (cancel previous)
this.searchControl.valueChanges.pipe(
  debounceTime(300),
  distinctUntilChanged(),
  switchMap(value => this.searchService.search(value))
).subscribe(results => {
  this.results = results; // Only latest request
});

// SOLUTION 2: takeUntil with search term
const searchTerm = new BehaviorSubject<string>('');
this.searchTerm.pipe(
  switchMap(term => this.searchService.search(term).pipe(
    takeUntil(this.searchTerm.pipe(
      skip(1),
      filter(newTerm => newTerm !== term)
    ))
  ))
).subscribe(results => {
  this.results = results;
});

// SOLUTION 3: Active request tracking
private activeRequest = 0;

search(value: string) {
  const requestId = ++this.activeRequest;
  this.searchService.search(value).subscribe(results => {
    if (requestId === this.activeRequest) {
      this.results = results; // Only process if still active
    }
  });
}

// PROBLEM: Multiple API calls
// User types: 'a', 'ab', 'abc', 'abcd', 'abcde'
// API called 5 times - too many!

// SOLUTION 1: debounceTime
this.searchControl.valueChanges.pipe(
  debounceTime(300), // Wait for typing pause
  distinctUntilChanged(),
  switchMap(value => this.searchService.search(value))
).subscribe(results => this.results = results);

