}

// PURE pipe (recommended for performance)
@Pipe({
  name: 'filter',
  pure: true // Only recalculates when input changes
})
export class FilterPipe implements PipeTransform {
  transform(items: any[], search: string): any[] {
    if (!items || !search) return items;
    return items.filter(item => item.name.includes(search));
  }
}

// IMPURE pipe (runs on every change detection)
@Pipe({
  name: 'filterImpure',
  pure: false // Recalculates on every change
})
export class FilterImpurePipe implements PipeTransform {
  transform(items: any[], search: string): any[] {
    console.log('Runs on every change detection');
    // WILL CAUSE PERFORMANCE ISSUES with large arrays
    return items.filter(item => item.name.includes(search));
  }
}

