// With TransferState to avoid re-fetching data
import { TransferState, makeStateKey } from '@angular/platform-browser';

const DATA_KEY = makeStateKey('product-data');

@Component({...})
export class ProductComponent {
  constructor(
    private transferState: TransferState,
    private http: HttpClient
  ) {}

  ngOnInit() {
    const data = this.transferState.get(DATA_KEY, null);

    if (data) {
      this.product = data;
      this.transferState.remove(DATA_KEY);
    } else {
      this.http.get('/api/product').subscribe(data => {
        this.product = data;
        this.transferState.set(DATA_KEY, data);
      });
    }
  }
}

// Actions
export const loadUsers = createAction('[Users] Load');
export const loadUsersSuccess = createAction('[Users] Load Success', props<{ users: User[] }>());
export const loadUsersFailure = createAction('[Users] Load Failure', props<{ error: string }>());

// Effects
@Injectable()
export class UserEffects {
  loadUsers$ = createEffect(() => this.actions$.pipe(
    ofType(loadUsers),
    switchMap(() => this.userService.getUsers().pipe(
      map(users => loadUsersSuccess({ users })),
      catchError(error => of(loadUsersFailure({ error: error.message })))
    ))
  ));

  // Effect with router navigation
  saveUser$ = createEffect(() => this.actions$.pipe(
    ofType(saveUser),
    concatMap(({ user }) => this.userService.saveUser(user).pipe(
      map(savedUser => saveUserSuccess({ user: savedUser })),
      catchError(error => of(saveUserFailure({ error: error.message })))
    ))
  ));

  // Effect that doesn't dispatch an action
  saveUserSuccess$ = createEffect(() => this.actions$.pipe(
    ofType(saveUserSuccess),
    tap(({ user }) => this.router.navigate(['/users', user.id])),
    map(() => showNotification({ message: 'User saved!' }))
  ), { dispatch: false });

  // Effect with multiple actions
  updateUsers$ = createEffect(() => this.actions$.pipe(
    ofType(loadUsersSuccess, saveUserSuccess),
    map(() => calculateTotalUsers())
  ));
}

