// State interface
interface UserState {
  users: User[];
  loading: boolean;
  error: string | null;
  selectedUserId: number | null;
}

// Basic selectors
export const selectUserState = (state: AppState) => state.users;

export const selectAllUsers = createSelector(
  selectUserState,
  (state: UserState) => state.users
);

export const selectUserLoading = createSelector(
  selectUserState,
  (state: UserState) => state.loading
);

// Memoized derived selector
export const selectActiveUsers = createSelector(
  selectAllUsers,
  (users: User[]) => users.filter(user => user.active)
);

// Selector with props
export const selectUserById = (userId: number) => createSelector(
  selectAllUsers,
  (users: User[]) => users.find(user => user.id === userId)
);

// Selector with multiple state slices
export const selectUserWithPermissions = createSelector(
  selectAllUsers,
  selectPermissions,
  (users, permissions) => users.map(user => ({
    ...user,
    permissions: permissions[user.role] || []
  }))
);

// Composable selectors
export const selectUserStats = createSelector(
  selectAllUsers,
  (users) => ({
    total: users.length,
    active: users.filter(u => u.active).length,
    inactive: users.filter(u => !u.active).length,
    roles: users.reduce((acc, u) => {
      acc[u.role] = (acc[u.role] || 0) + 1;
      return acc;
    }, {} as Record<string, number>)
  })
);

