// Example of AOT-compatible code
@Component({
  selector: 'app-example',
  template: `
    <!-- AOT works: static property -->
    <div>{{ publicProperty }}</div>

    <!-- AOT fails: private property -->
    <div>{{ privateProperty }}</div>

    <!-- AOT works: public method -->
    <div>{{ getPublic() }}</div>
  `
})
