// computed - derived state
@Component({...})
export class ShoppingCart {
  items = signal<Item[]>([]);

  // Computed values auto-update
  totalItems = computed(() => 
    this.items().reduce((sum, item) => sum + item.quantity, 0)
  );

  totalPrice = computed(() => 
    this.items().reduce((sum, item) => sum + item.price * item.quantity, 0)
  );

  // Computed with dependencies
  discount = computed(() => 
    this.totalItems() > 10 ? 0.1 : 0
  );

  finalPrice = computed(() => 
    this.totalPrice() * (1 - this.discount())
  );
}

// effect - side effects
@Component({...})
export class UserComponent {
  userId = signal<number | null>(null);
  user = signal<User | null>(null);

  // Effect for API calls
  userEffect = effect(() => {
    const id = this.userId();
    if (id) {
      this.loadUser(id);
    }
  });

  // Effect with cleanup
  intervalEffect = effect((onCleanup) => {
    const interval = setInterval(() => {
      this.tick.update(v => v + 1);
    }, 1000);

    onCleanup(() => clearInterval(interval));
  });

  // Effect with injection context
  private logger = inject(Logger);

  logEffect = effect(() => {
    this.logger.log('User changed:', this.userId());
  }, { injector: this.injector });
}

// linkedSignal - two-way sync (Angular 19+)
@Component({...})
export class FormComponent {
  // Linked signal with source
  sourceValue = signal('initial');

  // Synchronized with source
  linkedValue = linkedSignal(() => this.sourceValue());

  // Manual update without breaking link
  updateSource(value: string) {
    this.sourceValue.set(value); // linkedValue auto-updates
  }

  // Break link and set value
  updateLocal(value: string) {
    this.linkedValue.set(value);
  }

  // Linked signal with transform
  uppercaseLinked = linkedSignal({
    source: this.sourceValue,
    transform: (value: string) => value.toUpperCase()
  });
}

// Signal in services with singleton
@Injectable({ providedIn: 'root' })
export class AppStore {
  private state = signal<AppState>(initialState);

  // Expose readonly
  readonlyState = this.state.asReadonly();

  // Selectors
  selectUser = computed(() => this.state().user);
  selectLoading = computed(() => this.state().loading);

  // Actions
  setUser(user: User) {
    this.state.update(state => ({ ...state, user }));
  }

  setLoading(loading: boolean) {
    this.state.update(state => ({ ...state, loading }));
  }
}
